    data=json.loads(urllib.request.urlopen(f'https://api.water.noaa.gov/nwps/v1/gauges/{site}').read().decode('utf-8'))
    return data.get('flood',{}).get('categories',{}).get('minor',{}).get('stage')

def get_rating_points(site):
    listing=urllib.request.urlopen(f'https://waterdata.usgs.gov/nwisweb/get_ratings?site_no={site}&format=rdb').read().decode('utf-8')
    # find base rating url from listing lines
    base_url=None
    for line in listing.split('\n'):
        if line.startswith('USGS') and '\tbase\t' in line:
            parts=line.split('\t')
            base_url=parts[4]
    if not base_url:
        return None
    text=urllib.request.urlopen(base_url).read().decode('utf-8')
    points=[]
    for line in text.split('\n'):
        if not line or line.startswith('#'):
            continue
        if line.startswith('INDEP') or line[0].isalpha():
            continue
        parts=line.split('\t')
        if len(parts)<2:
            continue
        try:
            stage=float(parts[0])
            discharge=float(parts[1])
        except ValueError:
            continue
        points.append((stage, discharge))
    return points

def interpolate(points, stage):
    points=sorted(points)
    stages=[p[0] for p in points]
    if stage<stages[0] or stage>stages[-1]:
        return None
    i=bisect.bisect_left(stages, stage)
    if i==0:
        return points[0][1]
    if i==len(points):
        return points[-1][1]
    s0,q0=points[i-1]
    s1,q1=points[i]
    if s1==s0:
        return q0
    return q0+(q1-q0)*(stage-s0)/(s1-s0)

site='04031000'
minor_stage=get_minor_stage(site)
print('minor_stage',minor_stage)
points=get_rating_points(site)
print('points',len(points))
threshold=interpolate(points, minor_stage)
print('threshold',threshold)
