import csv, json, time, bisect
import urllib.request
from urllib.error import URLError, HTTPError

STATIONS_FILE='/root/data/michigan_stations.txt'
OUTPUT_FILE='/root/output/flood_results.csv'
START_DATE='2025-04-01'
END_DATE='2025-04-07'

opener = urllib.request.build_opener()
opener.addheaders = [('User-Agent', 'codex-cli/1.0')]
urllib.request.install_opener(opener)


def fetch_text(url, retries=3, timeout=30):
    for i in range(retries):
        try:
            with urllib.request.urlopen(url, timeout=timeout) as resp:
                return resp.read().decode('utf-8')
        except Exception:
            if i == retries - 1:
                raise
            time.sleep(1.5 * (i + 1))


def fetch_json(url, retries=3, timeout=30):
    text = fetch_text(url, retries=retries, timeout=timeout)
    return json.loads(text)


def get_minor_stage(site):
    url = f'https://api.water.noaa.gov/nwps/v1/gauges/{site}'
    data = fetch_json(url, retries=3, timeout=30)
    return data.get('flood', {}).get('categories', {}).get('minor', {}).get('stage')


def get_base_rating_url(site):
    url = f'https://waterdata.usgs.gov/nwisweb/get_ratings?site_no={site}&format=rdb'
    text = fetch_text(url, retries=3, timeout=30)
    base_url = None
    for line in text.split('\n'):
        if line.startswith('USGS') and '\tbase\t' in line:
            parts = line.split('\t')
            if len(parts) >= 5:
                base_url = parts[4].strip()
    return base_url


def get_rating_points(base_url):
    text = fetch_text(base_url, retries=3, timeout=30)
    points = []
    for line in text.split('\n'):
        if not line or line.startswith('#'):
            continue
        parts = line.split('\t')
        if len(parts) < 2:
            continue
        try:
            stage = float(parts[0])
            discharge = float(parts[1])
        except ValueError:
            continue
        points.append((stage, discharge))
    return points


def interpolate(points, stage):
    points = sorted(points)
    stages = [p[0] for p in points]
    if stage < stages[0] or stage > stages[-1]:
        return None
    i = bisect.bisect_left(stages, stage)
    if i == 0:
        return points[0][1]
    if i == len(points):
        return points[-1][1]
    s0, q0 = points[i - 1]
    s1, q1 = points[i]
    if s1 == s0:
        return q0
    return q0 + (q1 - q0) * (stage - s0) / (s1 - s0)


def get_daily_mean_discharge(site):
    url = (
        'https://waterservices.usgs.gov/nwis/dv/'
        f'?format=json&sites={site}&startDT={START_DATE}&endDT={END_DATE}'
        '&parameterCd=00060&statCd=00003'
    )
    data = fetch_json(url, retries=3, timeout=30)
    ts = data.get('value', {}).get('timeSeries', [])
    if not ts:
        return []
    values = ts[0].get('values', [])
    if not values:
        return []
    return values[0].get('value', [])


stations = [line.strip() for line in open(STATIONS_FILE) if line.strip()]
results = []

for site in stations:
    try:
        minor_stage = get_minor_stage(site)
        if minor_stage is None:
            continue
        base_url = get_base_rating_url(site)
        if not base_url:
            continue
        points = get_rating_points(base_url)
        if not points:
            continue
        threshold = interpolate(points, float(minor_stage))
        if threshold is None:
            continue
        daily_vals = get_daily_mean_discharge(site)
        flood_days = 0
        for v in daily_vals:
            try:
                val = float(v.get('value'))
            except (TypeError, ValueError):
                continue
            if val >= threshold:
                flood_days += 1
        if flood_days > 0:
